"""Collects the compressed Figma slices from this session's transcripts (main and subagents),
joins them per page and decodes them into figma/spec/<page id>.txt. Prints what is complete."""
import glob, json, os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import unlzw
P = os.path.expanduser('~/.claude/projects/-Users-kenneth-Projects-JusPrin')
S = '18e047ce-4892-4a44-8b70-c447eb34727c'
files = [f'{P}/{S}.jsonl'] + glob.glob(f'{P}/{S}/subagents/*.jsonl') + glob.glob('/private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin/' + S + '/tasks/*.output')
found = {}
def scan(o):
    if isinstance(o, str):
        if o.startswith('{"total":') and '"rawLen"' in o and '"part":"' in o:
            try: d = json.loads(o)
            except Exception: return
            found.setdefault((d['total'], d['rawLen']), set()).add(d['part'])
    elif isinstance(o, dict):
        for v in o.values(): scan(v)
    elif isinstance(o, list):
        for v in o: scan(v)
for f in files:
    for line in open(f, encoding='utf-8', errors='replace'):
        if 'rawLen' in line:
            try: scan(json.loads(line))
            except Exception: pass
os.makedirs('figma/spec', exist_ok=True)
A, B, IDX = unlzw.A, unlzw.B, unlzw.IDX
def first_line(part):
    # decode just enough of a slice-0 to read the PAGE line
    d = {i: chr(i) for i in range(128)}; nxt = 128; pos = 0; prev = None; out = ''
    while pos + 2 <= len(part) and len(out) < 200:
        c = IDX[part[pos]] * B + IDX[part[pos + 1]]; pos += 2
        if prev is None: prev = d[c]; out += prev; continue
        e = d[c] if c in d else prev + prev[0]
        out += e; d[nxt] = prev + e[0]; nxt += 1; prev = e
    return re.sub(r'`([0-9a-f]{4})', lambda m: chr(int(m.group(1), 16)), out).split('\n')[0]
for (total, raw), parts in sorted(found.items()):
    if raw < 400: continue
    heads = [p for p in parts if p.startswith('!s!d!j!h')]
    if not heads: print(f'total {total}: no first slice yet'); continue
    head = heads[0]
    rest = [p for p in parts if p is not head]
    need = (total + 20199) // 20200
    # order the remaining slices by trying to decode; slices are 20200 long except the last
    full = [p for p in rest if len(p) == 20200]; last = [p for p in rest if len(p) < 20200]
    name = first_line(head)
    if name.count('|') < 2: continue
    if 1 + len(rest) < need:
        print(f'{name}: have {1 + len(rest)} of {need} slices'); continue
    import itertools
    ok = None
    for perm in itertools.permutations(full):
        s = head + ''.join(perm) + ''.join(last)
        if len(s) != total: continue
        try:
            text = unlzw.decode(s)
        except Exception:
            continue
        if len(text) == raw or abs(len(text) - raw) < 50: ok = text; break
    if ok is None: print(f'{name}: slices present but could not be ordered'); continue
    pid = name.split('|')[1]
    v2 = bool(re.search(r'\|Z:[XHF]{2}(\||$)', ok, re.M))
    d = 'figma/spec2' if v2 else 'figma/spec'
    os.makedirs(d, exist_ok=True)
    open(f'{d}/{pid.replace(":", "-")}.txt', 'w', encoding='utf-8').write(ok)
    name += '  [v2]' if v2 else '  [v1]'
    print(f'{name}: complete, {len(ok)} chars, {ok.count(chr(10) + "@ ")} frames')

