#!/usr/bin/env python3
"""In Figma a later layer is drawn above an earlier one. In HTML an absolutely positioned element is drawn above
later siblings that are in normal flow, which hid content placed after an absolute background layer.
This gives such later siblings position:relative so the drawing order follows the layer order again.

Usage: fix_zorder.py [--write] <file>...   prints the files that change"""
import sys
from html.parser import HTMLParser

VOID = {'br', 'img', 'input', 'hr', 'meta', 'link', 'source', 'wbr'}


class P(HTMLParser):
    def __init__(self, text):
        super().__init__(convert_charrefs=False)
        self.text = text
        self.starts = [0]
        for ln in text.split('\n'): self.starts.append(self.starts[-1] + len(ln) + 1)
        self.stack = []      # each: dict(children=[...])
        self.edits = []      # offsets where 'position:relative;' is inserted

    def off(self):
        l, c = self.getpos(); return self.starts[l - 1] + c

    def handle_starttag(self, tag, attrs):
        raw = self.get_starttag_text(); o = self.off()
        style = dict(attrs).get('style') or ''
        node = {'tag': tag, 'style': style, 'off': o, 'raw': raw, 'children': []}
        if self.stack: self.stack[-1]['children'].append(node)
        if tag not in VOID: self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        if self.stack: self.stack[-1]['children'].append({'tag': tag, 'style': dict(attrs).get('style') or '', 'off': self.off(), 'raw': self.get_starttag_text(), 'children': []})

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i]['tag'] == tag:
                for n in self.stack[i:]: self.close(n)
                del self.stack[i:]; return

    def close(self, n):
        kids = [k for k in n['children'] if k['tag'] in ('div', 'span')]
        seen_abs = False
        for k in kids:
            if 'position:absolute' in k['style']: seen_abs = True
            elif seen_abs and 'position:' not in k['style'] and 'style="' in k['raw']:
                self.edits.append(k['off'] + k['raw'].index('style="') + len('style="'))


write = '--write' in sys.argv
total = 0
for f in [a for a in sys.argv[1:] if a != '--write']:
    t = open(f, encoding='utf-8').read()
    p = P(t); p.feed(t); p.close_all = None
    if not p.edits: continue
    total += len(p.edits)
    print(f.split('/')[-2] + '/' + f.split('/')[-1] if 'preview' in f else f.split('/')[-1], len(p.edits))
    if write:
        for o in sorted(p.edits, reverse=True):
            assert t[o - 7:o] == 'style="', t[o - 20:o + 20]
            t = t[:o] + 'position:relative;' + t[o:]
        open(f, 'w', encoding='utf-8').write(t)
print('total elements', total, file=sys.stderr)
